            <CameraHandler view={currentView} onFinished={() => setCurrentView(null)} />

            <GuideLinesRenderer lines={guideLines} />
            <AlignmentLinesRenderer lines={alignmentLines} />

            <group>
                {shapes.map(shape => (
                    <ShapeRenderer
                        key={shape.id}
                        shape={shape}
                        isSelected={selectedIds.includes(shape.id)}
                        pushPullState={ppState}
                        pushPullHandlers={pushPullHandlers}
                        drawingHandlers={drawingHandlers}
                        rotateHandlers={rotateHandlers}
                        setDraggingState={setDragging}
                        onShapeRef={onShapeRef}
                        shapeRefs={shapeRefs}
                        setAlignmentLines={setAlignmentLines}
                    />
                ))}
            </group>

            <InteractionLayer
                shapes={shapes}
                tool={tool}
                setCursorPos={setCursorPos}
                setSnapInfo={setSnapInfo}
                cursorPos={cursorPos}
                snapInfo={snapInfo}
                drawPoints={drawPoints}
                isDragging={isDrawDragging}
                drawingHeight={drawingHeight}
                typedInput={typedInput}
                guideCreating={guideCreating}
                rotateState={rotateState}
                drawingNormal={drawingNormal}
                isGizmoDragging={dragging}
                inferenceGuide={inferenceGuide}
                setInferenceGuide={setInferenceGuide}
                onPointerDown={handleDrawDown}
                onPointerUp={handleDrawUp}
                onClick={handleDrawClick}
            />

            <SelectionGizmo setDragging={setDragging} />

            <GizmoHelper alignment="bottom-right" margin={[80, 80]}>
                <GizmoViewport axisColors={['#ef4444', '#22c55e', '#3b82f6']} labelColor="black" />
            </GizmoHelper>
        </>
    );
};

const Viewport: React.FC = () => {
    const { tool, deselectAll } = useApp();

    return (
        <div 
            className={`w-full h-full bg-slate-100 relative ${tool === ToolType.SELECT ? 'cursor-default' : 'cursor-crosshair'}`}
            onContextMenu={(e) => e.preventDefault()}
        >
             <Canvas 
                shadows 
                camera={{ position: [10, 10, 10], fov: 45 }} 
                gl={{ preserveDrawingBuffer: true }}
                onPointerMissed={(e) => { 
                    if (tool === ToolType.SELECT && e.type === 'click') {
                         deselectAll();
                    }
                }}
            >
                <SceneContent />
            </Canvas>
        </div>
    );
};

export default Viewport;
